-- Enrich public.teams with the away team's geographic game/venue city from
-- data/teams.json so fan-mode (games/index.html) can resolve a stored
-- "City, State" away_team_city back to the team's fanbase. Additive + idempotent:
-- matches existing rows on (league, fanbase, mascot); never inserts or drops.
-- Generated by _gen_team_gamecity.mjs from data/teams.json (124 teams).

alter table public.teams add column if not exists game_city  text;
alter table public.teams add column if not exists venue_city text;

update public.teams t set
  game_city  = nullif(j.game_city, ''),
  venue_city = nullif(j.venue_city, '')
